<?php
require __DIR__.'/bootstrap.php';
if(!hasPermission('acces_admin')&&!hasPermission('acces_rh')){http_response_code(403);exit('Seules les Ressources humaines peuvent initialiser un contrat.');}
$error='';
$_SESSION['contract_create_csrf']??=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!hash_equals($_SESSION['contract_create_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée. Rechargez la page.');
        $payload=$_POST+['objet'=>'Objet à définir par le département technique','date_debut'=>date('Y-m-d'),'delai_jours'=>1,'taux_acompte'=>0,'retenue_garantie_taux'=>0];
        $id=$contractManager->create($payload,$_POST['ligne_ids']??[],(int)($_SESSION['user_id']??0));
        header('Location: workflow.php?id='.$id.'&etape=rh');exit;
    }catch(Throwable $e){$error=$e->getMessage();}
}
$chantiers=$pdo->query("SELECT c.id,c.code,c.titre,c.devis_id FROM chantier_banamur c WHERE c.archived_at IS NULL AND c.devis_id>0 ORDER BY c.code")->fetchAll();
$suppliers=$pdo->query("SELECT id_fournisseur,COALESCE(NULLIF(nom_commercial,''),raison_sociale,CONCAT(person_first_name,' ',person_last_name)) nom,telephone,email,adresse,ncc,rne FROM fournisseur_banamur WHERE actif=1 AND validation_status='approved' ORDER BY nom")->fetchAll();
$lines=$pdo->query("SELECT ld.id,ld.devis_id,ld.designation,COALESCE(NULLIF((SELECT SUM(ldb.montant) FROM debourse_banamur db JOIN ligne_debourse_banamur ldb ON ldb.debourse_id=db.id WHERE db.ligne_devis_id=ld.id),0),(SELECT SUM(db.montant_debourse) FROM debourse_banamur db WHERE db.ligne_devis_id=ld.id),0) total,EXISTS(SELECT 1 FROM contrat_sous_traitance_ligne cl JOIN contrat_sous_traitance c ON c.id=cl.contrat_id WHERE cl.ligne_devis_id=ld.id AND c.statut NOT IN ('resilie','solde')) locked FROM ligne_devis_banamur ld ORDER BY ld.id")->fetchAll();
$pageTitle='Initialiser un contrat';$activeMenu='contrats';require __DIR__.'/../decaissement/includes/header.php';require __DIR__.'/../decaissement/includes/navbar.php';?>
<link rel="stylesheet" href="contract-theme.css?v=<?= filemtime(__DIR__ . '/contract-theme.css') ?>">
<main class="contract-brand contract-create mx-auto max-w-5xl px-4 py-8"><header class="contract-hero p-6"><p class="text-xs font-black uppercase tracking-widest contract-eyebrow">Étape 1 · Ressources humaines</p><h1 class="mt-2 text-3xl font-black">Initialiser le dossier contractuel</h1><p class="mt-2 text-slate-300">Sélectionnez le chantier, le prestataire et les travaux. Les autres services compléteront ensuite leur partie dans l’ordre.</p></header><?php if($error):?><div class="mt-5 rounded-xl bg-rose-50 p-4 font-bold text-rose-800"><?=$h($error)?></div><?php endif;?><form method="post" class="mt-5 space-y-5"><input type="hidden" name="_csrf" value="<?=$h($_SESSION['contract_create_csrf'])?>"><section class="grid gap-4 rounded-xl border bg-white p-6 md:grid-cols-2"><label class="font-bold">Chantier<select required name="chantier_id" id="chantier" class="mt-2 w-full rounded-xl border p-3"><option value="">Sélectionner</option><?php foreach($chantiers as $c):?><option value="<?=$c['id']?>" data-devis="<?=$c['devis_id']?>"><?=$h($c['code'].' · '.$c['titre'])?></option><?php endforeach;?></select></label><label class="font-bold">Prestataire / fournisseur<select required name="fournisseur_id" id="fournisseur" class="mt-2 w-full rounded-xl border p-3"><option value="">Sélectionner</option><?php foreach($suppliers as $s):?><option value="<?=$s['id_fournisseur']?>" data-phone="<?=$h($s['telephone']??'')?>" data-email="<?=$h($s['email']??'')?>" data-address="<?=$h($s['adresse']??'')?>" data-ncc="<?=$h($s['ncc']??'')?>" data-rne="<?=$h($s['rne']??'')?>"><?=$h($s['nom'])?></option><?php endforeach;?></select></label></section><aside id="supplierCard" class="hidden rounded-xl border contract-soft p-5"><div class="flex items-start gap-4"><div id="supplierInitial" class="flex h-14 w-14 items-center justify-center rounded-full contract-primary text-xl font-bold">P</div><div><p class="text-xs font-black uppercase contract-reference">Fiche prestataire</p><h2 id="supplierName" class="mt-1 text-xl font-black"></h2><p id="supplierContact" class="mt-1 text-sm text-slate-700"></p><p id="supplierAddress" class="mt-1 text-sm text-slate-600"></p><a id="supplierMap" target="_blank" rel="noopener" class="mt-2 hidden text-sm font-bold contract-reference underline">Voir le lieu sur la carte</a></div></div></aside><section class="rounded-xl border bg-white p-6"><h2 class="text-xl font-black">Lignes de devis concernées</h2><p class="mt-1 text-sm text-slate-500">Le prix du contrat sera la somme des déboursés de ces lignes. Les lignes contractualisées ne seront plus disponibles dans une FEB ordinaire.</p><div id="lines" class="mt-4 grid gap-3"><?php foreach($lines as $l):?><label data-devis="<?=$l['devis_id']?>" class="line hidden rounded-xl border p-4 <?=$l['locked']?'bg-slate-100 opacity-60':'contract-line-available'?>"><input type="checkbox" name="ligne_ids[]" value="<?=$l['id']?>" <?=$l['locked']?'disabled':''?>> <b><?=$h($l['designation'])?></b><span class="float-right font-black"><?=number_format((float)$l['total'],0,',',' ')?> FCFA</span><?php if($l['locked']):?><small class="block font-bold text-slate-600">Ligne sous contrat — indisponible</small><?php endif;?></label><?php endforeach;?></div></section><button class="rounded-xl contract-primary px-6 py-3 font-bold">Initialiser et compléter la partie RH</button></form></main><script>const c=document.getElementById('chantier'),ls=[...document.querySelectorAll('.line')],supplier=document.getElementById('fournisseur'),card=document.getElementById('supplierCard');function show(){const d=c.selectedOptions[0]?.dataset.devis;ls.forEach(x=>x.classList.toggle('hidden',x.dataset.devis!==d));}function showSupplier(){const o=supplier.selectedOptions[0],name=o?.value?o.textContent.trim():'',address=o?.dataset.address||'';card.classList.toggle('hidden',!name);if(!name)return;document.getElementById('supplierName').textContent=name;document.getElementById('supplierInitial').textContent=name.charAt(0).toUpperCase();document.getElementById('supplierContact').textContent=[o.dataset.phone,o.dataset.email,o.dataset.ncc&&'NCC '+o.dataset.ncc,o.dataset.rne&&'RNE '+o.dataset.rne].filter(Boolean).join(' · ')||'Coordonnées non renseignées';document.getElementById('supplierAddress').textContent=address||'Adresse non renseignée';const map=document.getElementById('supplierMap');map.classList.toggle('hidden',!address);map.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address);}c.addEventListener('change',show);supplier.addEventListener('change',showSupplier);show();showSupplier();</script><?php require __DIR__.'/../decaissement/includes/footer.php';?>

